pinMode(port, INPUT_PULLUP);
value = digitalRead(port);
Serial.println(value);

examples:
void setup() {
  Serial.begin(115200);
  pinMode(1, INPUT_PULLUP);
  pinMode(2, INPUT_PULLUP);
}

void loop() {
  int swA1State = digitalRead(1);
  int swA2State = digitalRead(2);

  Serial.print("A1 SW: ");
  Serial.println(swA1State);

  Serial.print("A2 Sw: ");
  Serial.println(swA2State);

  delay(500);
}

void setup() {
  pinMode(1, OUTPUT);
}

void loop() {
  digitalWrite(1, HIGH);
  delay(1000);
  digitalWrite(1, LOW);
  delay(1000);
}

void setup() {
  Serial.begin(115200);
}

void loop() {
  int a1Value = analogRead(1);
  int a2Value = analogRead(2);

  Serial.print("A1: ");
  Serial.println(a1Value);

  Serial.print("A2: ");
  Serial.println(a2Value);

  delay(200);
}

const int pwmFreq = 5000;
const int pwmResolution = 8;

void setup() {
  ledcAttach(1, pwmFreq, pwmResolution);
}

void loop() {
  ledcWrite(1, 255);
  delay(1000);
  ledcWrite(1, 128);
}

