sections.description:
Library Name: Arduino

Include Syntax:
#include <Arduino.h>

Serial.begin(115200);
analogReadResolution(12);
Initializes serial communication and sets the ADC resolution.

examples:
#include <Arduino.h>

#define POT_PIN 8

void setup() {
  Serial.begin(115200);
  analogReadResolution(12);
}

void loop() {
  int rawValue = analogRead(POT_PIN);

  Serial.println(rawValue);

  delay(200);
}

sections.description:
Create a servo object and attach it to a pin in the setup() function:

Servo myServo;
myServo.attach(SERVO_PIN, 500, 2400);

Control the servo angle inside the loop() function using:

myServo.write(angle);

examples:
#include <ESP32Servo.h>

Servo myServo;

#define SERVO_PIN 1

void setup() {
  myServo.attach(SERVO_PIN, 500, 2400);
}

void loop() {
  myServo.write(90);  // Rotate to 90 degrees
  delay(1000);

  myServo.write(0);   // Rotate back to 0 degrees
  delay(1000);
}

sections.description:
Initialize the I2C communication and OLED display inside setup():

Wire.begin(SDA_PIN, SCL_PIN);
display.begin(SSD1306_SWITCHCAPVCC, SCREEN_ADDRESS);

display.clearDisplay();
display.setTextSize(size);
display.setTextColor(SSD1306_WHITE);
display.setCursor(x, y);
display.println("text");
display.display();

examples:
#include <Wire.h>
#include <Adafruit_GFX.h>
#include <Adafruit_SSD1306.h>

#define SCREEN_WIDTH 128
#define SCREEN_HEIGHT 64
#define OLED_RESET -1
#define SCREEN_ADDRESS 0x3C

#define SDA_PIN 48
#define SCL_PIN 47

Adafruit_SSD1306 display(SCREEN_WIDTH, SCREEN_HEIGHT, &Wire, OLED_RESET);

void setup() {
  Wire.begin(SDA_PIN, SCL_PIN);

  if (!display.begin(SSD1306_SWITCHCAPVCC, SCREEN_ADDRESS)) {
    Serial.println("SSD1306 allocation failed");
    while (1);
  }

  display.clearDisplay();
  display.setTextSize(2);
  display.setTextColor(SSD1306_WHITE);
  display.setCursor(0, 0);
  display.println("Hi World!");
  display.display();
}

void loop() {
}

sections.description:
1.	Library Name: FS, SD_MMC

2.	Include Syntax:
	#include "FS.h"
	#include "SD_MMC.h"

SD_MMC.setPins(clk, cmd, d0);
SD_MMC.begin("/sdcard", true);
Initializes the SD card using MMC interface and sets custom SD pins.

File file = SD_MMC.open("/filename.txt", FILE_WRITE);
file.println("text data");
file.close();

examples:
#include <Arduino.h>
#include "FS.h"
#include "SD_MMC.h"

void setup() {
  Serial.begin(115200);
 delay(500);

  SD_MMC.setPins(39, 38, 40);

  if (!SD_MMC.begin("/sdcard", true)) {
    Serial.println("SD_MMC begin failed");
    return;
  }

  File f = SD_MMC.open("/hello.txt", FILE_WRITE);
  if (f) {
    f.println("Hello World");
    f.close();
  }
}

void loop() {
}

