#include <Arduino.h>
#include "FS.h"
#include "SD_MMC.h"

void setup() {
  Serial.begin(115200);
delay(500);
  SD_MMC.setPins(39, 38, 40);

  if (!SD_MMC.begin("/sdcard", true)) {
    Serial.println("SD_MMC Mount Failed");
    return;
  }

  File file = SD_MMC.open("/hello.txt", FILE_READ);
  while (file.available()) {
    Serial.write(file.read());
  }
